using System.Numerics;
using System.Reflection;
using System.Text.Json;
using ByteEngine.Core;
using ByteEngine.Core.Gameplay;
using ByteEngine.Core.Scene;
using KarlsonDemo.Plugin;
internal static class MiningWeaponSupportCheck
{
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);Console.WriteLine("PASS WEAPON SUPPORT "+message);}
 public static void Run(Scene scene,MiningOperation3D op){var host=new SceneManager();host.LoadScene(scene);typeof(Time).GetMethod("Update",BindingFlags.Static|BindingFlags.NonPublic)!.Invoke(null,[.05d]);typeof(Scene).GetMethod("UpdateInternal",BindingFlags.Instance|BindingFlags.NonPublic)!.Invoke(scene,null);op.TargetEnabled=false;op.SkipCampTutorial();void Set(string name,object value)=>typeof(MiningOperation3D).GetProperty(name)!.SetValue(op,value);Set("Credits",100000);Set("RefinedOre",1000);Set("CompletedRounds",10);
 var trade=op.GameObject.GetComponent<MiningTrade3D>()!;trade.Initialize();var shop=op.GameObject.GetComponent<MiningResearchStation3D>()!;var planner=op.DefencePlanner!;
 Check(trade.BuyResearch("rd")&&shop.PlaceStation(new(-15,0,-25)),"R&D unlock and station placement work");int ore=op.RefinedOre;
 Check(!shop.Buy(4)&&shop.MineStock==0&&op.RefinedOre==ore,"R&D alone cannot buy mines or charge ore");Check(!shop.Buy(5)&&shop.SentryStock==0&&op.RefinedOre==ore,"extra sentry orders require sentry licence");Check(!planner.SelectBuild(MiningDefenseKind.Mine),"unlicensed mines cannot enter placement");
 Check(trade.BuyResearch("mine")&&shop.Buy(4)&&shop.Buy(4),"mine licence enables repeat purchases");Check(shop.MineStock==2&&op.RefinedOre==ore-2*shop.MineOreCost,"each mine order charges exactly one kit");
 Check(trade.BuyResearch("shotgun")&&trade.BuyResearch("sentry"),"sentry licence unlocks normally");int free=planner.Available(MiningDefenseKind.Sentry);ore=op.RefinedOre;Check(free==1&&shop.Buy(5)&&shop.Buy(5),"sentry licence grants a free kit and permits additional orders");Check(shop.SentryStock==2&&op.RefinedOre==ore-110&&planner.Available(MiningDefenseKind.Sentry)==3,"extra sentries cost55 refined each and retain the free licence kit");
 var actor=scene.FindGameObject(op.PlayerObjectId)!;for(int k=0;k<3;k++){Check(planner.SelectBuild(MiningDefenseKind.Sentry),"sentry kit selectable "+k);bool placed=false;for(int n=0;n<24&&!placed;n++){float a=n*MathF.Tau/24;placed=planner.TryPlace(actor.Transform.WorldPosition+new Vector3(MathF.Cos(a)*(10+k*5),0,MathF.Sin(a)*(10+k*5)));}Check(placed,"sentry kit placed "+k);}Check(shop.SentryStock==0&&planner.Available(MiningDefenseKind.Sentry)==0&&planner.LiveDefences.Count(d=>d.Kind==MiningDefenseKind.Sentry)==3,"placement consumes purchased kits without duplicating licence allowance");
 var destroyed=planner.LiveDefences.First(d=>d.Kind==MiningDefenseKind.Sentry);planner.Retire(destroyed,true);scene.DestroyGameObject(destroyed.GameObject);Check(planner.Available(MiningDefenseKind.Sentry)==1&&planner.ReplacementCost(MiningDefenseKind.Sentry)==20,"destroyed purchased sentry retains existing replacement rules");Check(shop.Buy(5),"another sentry order remains available");shop.PersistSupport();var support=JsonSerializer.Deserialize<MiningResearchStation3D.SupportSave>(op.ResearchSupportState,new JsonSerializerOptions{IncludeFields=true})!;Check(support.SentryStock==1&&support.MineStock==2,"unplaced sentry and mine kits persist in support save");
 var old=new MiningTrade3D.State{Purchased=["pistol-handling","rifle-handling"],Ranks=new(){{"pistol-handling",2},{"rifle-handling",3}}};MiningTrade3D.MigrateWeaponUpgradeState(old);string once=JsonSerializer.Serialize(old);MiningTrade3D.MigrateWeaponUpgradeState(old);Check(once==JsonSerializer.Serialize(old)&&old.Ranks!["pistol-reload"]==2&&old.Ranks["pistol-magazine"]==2&&old.Ranks["rifle-accuracy"]==3&&!old.Ranks.ContainsKey("pistol-damage"),"bundle migration preserves purchased effects once and does not grant free damage");var custom=new MiningTrade3D.State{Purchased=["pistol-handling"]};MiningTrade3D.MigrateWeaponUpgradeState(custom,new HashSet<string>{"pistol-handling"});Check(custom.Purchased!.Contains("pistol-handling"),"older custom catalogues retain their original bundle");
 Check(trade.BuyResearch("ar"),"rifle licence remains purchasable");var definitions=scene.GetComponentsSnapshot<WeaponDefinition3D>().Where(d=>d.RequiredResearchId is "" or "ar" or "shotgun").GroupBy(d=>d.RequiredResearchId).ToDictionary(g=>g.Key,g=>g.First());
 foreach(var family in new[]{("pistol","",2),("rifle","ar",4),("shotgun","shotgun",1)}){var d=definitions[family.Item2];int magazine=d.MagazineCapacity;float reload=d.ReloadSeconds,damage=d.DamagePerPellet;var others=definitions.Values.Where(x=>x!=d).ToDictionary(x=>x,x=>x.DamagePerPellet);Check(trade.ResearchCost(family.Item1+"-reload")<=45&&trade.ResearchCost(family.Item1+"-magazine")<=50&&trade.ResearchCost(family.Item1+"-damage")<=55,family.Item1+" starting upgrades are affordable");Check(trade.BuyResearch(family.Item1+"-reload")&&Math.Abs(d.ReloadSeconds-reload/1.15f)<.001f&&d.MagazineCapacity==magazine&&d.DamagePerPellet==damage,family.Item1+" reload purchase changes only reload speed");Check(trade.BuyResearch(family.Item1+"-magazine")&&d.MagazineCapacity==magazine+family.Item3&&Math.Abs(d.ReloadSeconds-reload/1.15f)<.001f,family.Item1+" magazine purchase is independent");Check(trade.BuyResearch(family.Item1+"-damage")&&Math.Abs(d.DamagePerPellet-damage*1.12f)<.001f&&others.All(x=>x.Key.DamagePerPellet==x.Value),family.Item1+" damage upgrade affects only its own gun");Check(trade.BuyResearch(family.Item1+"-damage")&&Math.Abs(d.DamagePerPellet-damage*1.24f)<.001f,family.Item1+" damage ranks apply from baseline without compounding");}
 host.UnloadScene();}
}
